pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.warp(100);
        vm.deal(address(this), 20 ether);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call must succeed");

        vm.warp(101);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second call must revert on the correct contract");
    }
}
